using Ginecologia.Modules.Promociones.Application;
using Ginecologia.Modules.Promociones.Domain;
using Microsoft.EntityFrameworkCore;
namespace Ginecologia.Modules.Promociones.Infrastructure;
public sealed class PromotionRepository(PromocionesDbContext db) : IPromotionRepository
{ public Task<Promotion?> FindByIdAsync(Guid id, CancellationToken ct = default) => db.Promotions.SingleOrDefaultAsync(x => x.Id == id, ct); public async Task<PagedPromotionResult<Promotion>> ListAsync(PromotionListQuery query, CancellationToken ct = default) { IQueryable<Promotion> source = db.Promotions.AsNoTracking(); if (query.PatientId is { } patientId) source = source.Where(x => x.PatientId == patientId); if (query.Estado is { } estado) source = source.Where(x => x.Estado == estado); var total = await source.CountAsync(ct); var items = await source.OrderByDescending(x => x.FechaGenerada).ThenByDescending(x => x.CreatedAtUtc).Skip((query.Page - 1) * query.PageSize).Take(query.PageSize).ToListAsync(ct); return new(items, total, query.Page, query.PageSize); } public Task<bool> ExistsForPatientOnDateAsync(Guid patientId, PromotionType tipo, DateOnly fecha, CancellationToken ct = default) => db.Promotions.AnyAsync(x => x.PatientId == patientId && x.Tipo == tipo && x.FechaGenerada == fecha, ct); public Task AddAsync(Promotion item, CancellationToken ct = default) => db.Promotions.AddAsync(item, ct).AsTask(); public Task SaveChangesAsync(CancellationToken ct = default) => db.SaveChangesAsync(ct); }
